package tech.wenisch.smtp2x.service;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import tech.wenisch.smtp2x.domain.ActionType;
@Component public class WebhookActionHandler implements ActionHandler {
 private final ObjectMapper json; private final SecretCipher secrets; private final ActionHttpClientFactory clients; public WebhookActionHandler(ObjectMapper json,SecretCipher secrets,ActionHttpClientFactory clients){this.json=json;this.secrets=secrets;this.clients=clients;} public ActionType type(){return ActionType.WEBHOOK;}
 public DeliveryResult deliver(MessageData data,JsonNode c)throws DeliveryException{try{String url=c.path("url").asText();if(url.isBlank())throw new DeliveryException("Webhook action requires url",false);ObjectNode body=json.createObjectNode();body.put("version","1");body.put("messageId",data.message().getId().toString());body.put("from",data.message().getEnvelopeFrom());body.put("subject",data.message().getSubject());body.put("text",data.message().getTextBody());body.set("recipients",json.valueToTree(data.recipients()));body.set("attachments",json.valueToTree(data.attachments().stream().map(a->Map.of("filename",a.getFilename(),"contentType",Optional.ofNullable(a.getContentType()).orElse(""),"size",a.getSizeBytes())).toList()));JsonNode custom=c.get("payload");if(custom!=null&&!custom.isNull())body=(ObjectNode)custom.deepCopy(); RestClient.RequestBodySpec r=clients.forConfiguration(c).post().uri(url).contentType(MediaType.APPLICATION_JSON);c.path("headers").fields().forEachRemaining(e->r.header(e.getKey(),e.getValue().asText()));String bearer=secrets.decrypt(c.path("bearerToken").asText());if(!bearer.isBlank())r.header(HttpHeaders.AUTHORIZATION,"Bearer "+bearer);ResponseEntity<String> response=r.body(json.writeValueAsString(body)).retrieve().toEntity(String.class);return new DeliveryResult(url,"Webhook returned "+response.getStatusCode(),"");}catch(DeliveryException e){throw e;}catch(Exception e){throw new DeliveryException("Webhook delivery failed",true,e);}}
}
